const sumFinanceExpensesByCategory = `-- name: SumFinanceExpensesByCategory :many
SELECT c.uuid AS category_uuid, c.name AS category_name,
       COALESCE(SUM(t.amount), 0)::numeric AS total
FROM finance_transactions t
JOIN finance_categories c ON c.id = t.category_id
WHERE t.organization_id = $1
  AND t.type = 'expense'
  AND t.status = 'posted'
  AND t.transaction_date >= $2
  AND t.transaction_date <= $3
GROUP BY c.uuid, c.name
ORDER BY total DESC
`

type SumFinanceExpensesByCategoryParams struct {
	OrganizationID    int64       `json:"organization_id"`
	TransactionDate   pgtype.Date `json:"transaction_date"`
	TransactionDate_2 pgtype.Date `json:"transaction_date_2"`
}

